return {rwnpc01={id="rwnpc01",title="BLU时间缺失大师NOR",dsc="看模样像是个幼童，但因为实在太小只，所以判断不清性别。明明看上去是个小孩，说话的口气却是个十足的大人。小小的身子在桌子前忙得团团转，根本停不下来。",sex="野兽",age=3,looks=25,showequip={},withCorpse=0},rwnpc02={id="rwnpc02",dsc="他正是红松阁的表面首脑，实为高级打杂， 每天身份于压榨别人和被压榨之间来回切换，练就出一身厚脸皮神功。",sex="男",age=30,looks=20,showequip={},withCorpse=0},rwnpc03={id="rwnpc03",dsc="此人曾是戍卫边疆的武官，身长八尺有余，豹头环眼，壮如蛮牛，皮肤黝黑，下颚上留有钢针般遒劲的浓密胡须，却不知为何住在了这平安小镇内。",sex="男",age=49,looks=18,showequip={},withCorpse=0},rwnpc04={id="rwnpc04",dsc="此人头戴斗笠看不清面容，但其气息内敛，应当是个高手。",sex="野兽",age=30,looks=20,showequip={},withCorpse=0},rwnpc05={id="rwnpc05",title="BLU工具人NOR",dsc="她是红松阁的新人。勤勤恳恳，任劳任怨地完成阁中的工作。",sex="女",age=23,looks=10,showequip={},withCorpse=0},rwnpc06={id="rwnpc06",dsc="此人身着黑衣，头戴黑纱斗笠，但其气息内敛，应当是个高手。",sex="野兽",age=30,looks=20,showequip={},withCorpse=0},rwnpc07={id="rwnpc07",dsc="此人身着蓑衣，头戴斗笠看不清面容，手抱长刀，看起来是个高手。",sex="野兽",age=30,looks=20,showequip={},withCorpse=0},rwnpc08={id="rwnpc08",title="PNK忙碌教主NOR",dsc="此女衣着华丽，但两只长袖已被她用丝带绑起，双手各持一笔，在书籍上写写画画。",sex="女",age=29,looks=19,showequip={},withCorpse=0},rwnpc09={id="rwnpc09",dsc="他一身漆黑，看着与吉吉十分相似，但眼神木讷。非要说的话，他或许是吉吉对看书的执念。",sex="野兽",age=30,looks=20,showequip={},withCorpse=0},rwnpc10={id="rwnpc10",dsc="他一身漆黑，蒙着脸，看不清面容，但他的眼神充满了怨念。",sex="野兽",age=30,looks=20,showequip={},withCorpse=0},rwnpc11={id="rwnpc11",dsc="他清爽利落，一身文人打扮，手持一支徽笔，指点天下，隐隐有睥睨之姿。",sex="男",age=30,looks=27,showequip={},withCorpse=0},rwnpc12={id="rwnpc12",dsc="她是负责接引游客的接引人。时而安静，低头处理自己的事物，时而活泼，与游客们打成一片。",sex="女",age=26,looks=22,showequip={},withCorpse=0},rwnpc13={id="rwnpc13",dsc="他手如鸡爪，面若鼠狼，身似骷髅。他双腿已断，似乎是从悬崖上摔落到谷底，只能以谷底的蛇虫鼠蚁为食。",sex="男",age=60,looks=12,showequip={},withCorpse=0},rwnpc14={id="rwnpc14",dsc="他手臂绘有淡淡的刺青，一头长发用木簪盘起，虽然身为男子，长相却比寻常女子还要秀气。",sex="男",age=20,looks=24,showequip={},withCorpse=0},rwnpc15={id="rwnpc15",dsc="他左手一支笔，右手一支笔。左手细笔急促，将面具仔细轻描；右手长笔飒挥，将山水描摹于纸上。",sex="男",age=20,looks=19,showequip={},withCorpse=0},rwnpc16={id="rwnpc16",dsc="他容貌如画，漂亮得根本就不似真人这种容貌，这种风仪，根本就已经超越了一切人类的美丽。这种超越的男女，超越了世俗的美态，竟是已不能用言词来形容。",sex="男",age=23,looks=28,showequip={},withCorpse=0},rwnpc17={id="rwnpc17",dsc="只见他白衣洁净，如琼枝一树，栽种在青山绿水之间，尽得天地之精华；又似昆仑美玉，落于东南一隅，散发着淡淡华彩，不由得让人一呆。",sex="男",age=34,looks=30,showequip={},withCorpse=0},rwnpc18={id="rwnpc18",dsc="盛唐阁二阁主，平日虽不坐镇这阁内，但其威严依然让属下噤若寒蝉。",sex="男",age=30,looks=29,showequip={},withCorpse=0},rwnpc20={id="rwnpc20",dsc="他宽衣宽袍，戴着一个木质面具，看不出男女，也看不清他什么模样。",sex="野兽",age=23,looks=10,showequip={},withCorpse=0}}0000